const baseUrl = $env.SONARR_URL;
const apiKey = $env.SONARR_API_KEY;

const volumes = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/api/v3/diskspace`,
  qs: { apikey: apiKey },
  json: true,
});

return volumes.map((v) => ({
  json: {
    label: `hdd1 (${v.path})`,
    freeBytes: v.freeSpace,
    totalBytes: v.totalSpace,
  },
  pairedItem: { item: 0 },
}));

